INSERT INTO feature VALUES('levitated-descriptions','descriptions','Levitated descriptions','signatures-as-values','implemented','notable',NULL,'A code universe of descriptions, first-order but for one function former over value types (higher-order-fields), populated by declarations, drives generic programs, rule faces and multi-output arities. Sort descriptions carry a representability bit and the restricted binder π⁺ (a binder over a representable sort), refused by check_desc otherwise. A theory block lowers to its description and the rendering reparses to the same description (#724); Theory carries representability and π⁺ (the port rule), its identity bytes moved once with their cause; TheoryDesc is read off the Theory value by theory-levitation''s TheoryValue::description, which the reader calls (#1384).','theory-levitation','corpus/model/desc/desc-inspect.gandr','corpus/model/desc/desc-inspect.gandr',NULL);
